INSERT INTO `quest_template_locale` (`ID`, `locale`, `Title`, `Details`, `Objectives`, `EndText`, `CompletedText`, `ObjectiveText1`, `ObjectiveText2`, `ObjectiveText3`, `ObjectiveText4`, `VerifiedBuild`) VALUES
(13405, 'koKR', 'Wezwanie do boju: Wybrzeże Pradawnych', 'Walka w Północnej Grani toczy się nie tylko z armiami Króla Lisza, ale też z wojskami Hordy.$B$BNa Wybrzeżu Pradawnych odnaleziono potężny relikt tytanów. Jak może wiesz, my, krasnoludy, od lat strzeżemy takich artefaktów i dlatego to my jesteśmy ich prawowitymi opiekunami.$B$BTym razem Horda bardzo się zainteresowała wykradzeniem reliktu z ruin tytanów. Z pewnością użyje go jako broni przeciwko nam – musimy zrobić wszystko, by ją powstrzymać.', 'Wygraj bitwę na Wybrzeżu Pradawnych i wróć do generała brygady Przymierza w dowolnej stolicy Przymierza, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo na Wybrzeżu Pradawnych', '', '', '', '', '', 0),
(13407, 'koKR', 'Wezwanie do boju: Wybrzeże Pradawnych', 'To, że maszerujemy na Północną Grań, by zmiażdżyć Plagę, nie znaczy, że możemy sobie odpuścić miażdżenie Przymierza.$B$BTe krasnoludy z Ligi Odkrywców odnalazły miejsce, w którym spoczywa potężny relikt tytanów, i niech nas szlag, jeśli pozwolimy, by Przymierze przejęło nad nim kontrolę.$B$BIdź, $N, i zniszcz naszych wrogów. Niech zrozumieją, że gdziekolwiek się spotkamy, pozostaną naszymi zaprzysięgłymi wrogami.', 'Wygraj bitwę na Wybrzeżu Pradawnych i wróć do zwiastuna wojny Hordy w dowolnej stolicy Hordy, w Zimościsku, Dalaranie lub Shattrath.', 'Zwycięstwo na Wybrzeżu Pradawnych', '', '', '', '', '', 0);
INSERT INTO `quest_offer_reward_locale` (`ID`, `locale`, `RewardText`, `VerifiedBuild`) VALUES
(13405, 'koKR', 'Świetna robota, $N! Dzięki twojej pomocy Wybrzeże Pradawnych znajdzie się pod pełną kontrolą Przymierza.', 0),
(13407, 'koKR', 'Przynosisz nam wielki honor, $N! Słabeusze z Przymierza muszą zostać zmiażdżeni pod butem potężnej Hordy!', 0);
INSERT INTO `quest_request_items_locale` (`ID`, `locale`, `CompletionText`, `VerifiedBuild`) VALUES
(13405, 'koKR', 'Jakie wieści przynosisz z frontu, $N?', 0),
(13407, 'koKR', '$GWróciłeś:Wróciłaś;! $GOdniosłeś:Odniosłaś; zwycięstwo, $n?', 0);
